// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 _val1, uint256 _val2) internal {
        vm.assume(true);
        try c.Initialized() {} catch { return; }
        uint256 minSumBefore;
        try c.MinSum() returns (uint256 __r) { minSumBefore = __r; } catch { return; }
        try c.SetMinSum(_val1) {} catch { return; }
        try c.SetMinSum(_val2) {} catch { return; }
        uint256 minSumAfter;
        try c.MinSum() returns (uint256 __r) { minSumAfter = __r; } catch { return; }
        assertTrue(minSumAfter == minSumBefore);
    }

    function testFuzz_run(uint256 _val1, uint256 _val2) public {
        _run(_val1, _val2);
    }

    receive() external payable {}
}
